(42556, 'Numbers 35:21', 'Numbers', 35, 21, 'یا هغه په سوک ووهي، هغه د هغه کس د قتل په اړه مجرم دی او باید ووژل شي. د وژل شوي کس یو ډېر نژدې خپلوان دا مسوولیت لري چې قاتل ووژني. کله چې هغه راپیدا کړي، نو باید ویې وژني.', 'یا هغه په سوک ووهی، هغه د هغه کس د قتل په اره مجرم دی او باید ووژل شی. د وژل شوی کس یو دېر نژدې خپلوان دا مسوولیت لری چې قاتل ووژنی. کله چې هغه راپیدا کری، نو باید ویې وژنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_35_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(42557, 'Numbers 35:22', 'Numbers', 35, 22, 'خو فرض کړئ څوک په سهوې سره یو داسې کس مړ کړي چې د هغه سره کینه نه لري، که هغه په ټېل وهلو وي یا په کوم شي باندې په ویشتلو سره.', 'خو فرض کری چوک په سهوې سره یو داسې کس مر کری چې د هغه سره کینه نه لری، که هغه په تېل وهلو وی یا په کوم شی باندې په ویشتلو سره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_35_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(42558, 'Numbers 35:23', 'Numbers', 35, 23, 'یا د هغه فکر نه وي او یو داسې سړی په تیږه باندې په ویشتلو مړ کړي چې د هغه نیت نه وي چې هغه ژوبل کړي او د هغه دښمن نه وي.', 'یا د هغه فکر نه وی او یو داسې سری په تیزه باندې په ویشتلو مر کری چې د هغه نیت نه وی چې هغه ژوبل کری او د هغه دشمن نه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_35_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(42559, 'Numbers 35:24', 'Numbers', 35, 24, 'نو په داسې حالاتو کې دې د هغه ځای خلک د هغه چا په حق کې پرېکړه وکړي چې کس یې مړ کړی دی، نه د مړي د خپلوانو څخه د هغه کس په حق کې چې د بدل اخیستلو په لټه کې دی.', 'نو په داسې حالاتو کې دې د هغه جای خلک د هغه چا په حق کې پرېکره وکری چې کس یې مر کری دی، نه د مری د خپلوانو چخه د هغه کس په حق کې چې د بدل اخیستلو په لته کې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_35_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(42560, 'Numbers 35:25', 'Numbers', 35, 25, 'ټولنه باید هغه سړی چې په قتل باندې تورن دی د وژل شوي کس د خپلوان څخه خلاص کړي او هغه باید د پناه اخیستنې هغه ښار ته چې هغه ورتښتېدلی ؤ، بېرته ولېږي. هغه باید د لوی کاهن تر مړینې پورې په هغه ښار کې واوسیږي.', 'تولنه باید هغه سری چې په قتل باندې تورن دی د وژل شوی کس د خپلوان چخه خلاص کری او هغه باید د پناه اخیستنې هغه شار ته چې هغه ورتشتېدلی و، بېرته ولېزی. هغه باید د لوی کاهن تر مرینې پورې په هغه شار کې واوسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_35_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842);